updated as (select item,snapshot||jsonb_build_object('contentVersion','literacy-mock-v11','adaptiveAreaVersion','areas-v6')||coalesce(patches->(snapshot->>'id'),'{}'::jsonb) snapshot from source cross join route)
insert into literacy_mock_incoming select jsonb_set(item,'{itemSnapshot}',snapshot) from updated;
do $$begin
 if exists(select 1 from literacy_mock_incoming incoming join public.literacy_mock_items old on old.id=incoming.item->>'id' and old.content_version='literacy-mock-v11' where old.item is distinct from incoming.item) then raise exception 'Cannot rewrite immutable V11 publication'; end if;
end; $$;
insert into public.literacy_mock_items(id,content_version,item) select item->>'id','literacy-mock-v11',item from literacy_mock_incoming on conflict(id,content_version) do nothing;
insert into public.literacy_mock_publications(content_version,item_count) values('literacy-mock-v11',12568) on conflict(content_version) do nothing;
do $$begin
 if (select count(*) from public.literacy_mock_items where content_version='literacy-mock-v11')<>12568 then raise exception 'Incomplete V11 publication'; end if;
end; $$;
